/**
 * promptMarkdownUtils.mjs — build-time prompt bundler.
 *
 * Reads all .md files from src/lib/prompts/system/ in alphabetical order,
 * concatenates them, and writes a TypeScript module that exports the
 * assembled base prompt as a string. This runs:
 *   - Once during `vite build` (production)
 *   - On every dev launch via smart-dev.mjs
 *   - Manually: `node build/promptMarkdownUtils.mjs`
 *
 * The generated file (_system-prompt-bundle.ts) is gitignored — it's a
 * build artifact, not source. Editing prompt content means editing the
 * .md files, then rebuilding.
 *
 * User overrides: if ~/.tide/prompts/ (or ~/.tide-dev/prompts/) contains
 * .md files, they're appended AFTER the built-in prompts — allowing users
 * to add custom instructions without modifying the app source.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');

const PROMPTS_DIR = path.join(ROOT, 'src', 'lib', 'prompts', 'system');
const AGENTS_DIR = path.join(ROOT, 'src', 'lib', 'prompts', 'agents');
const TOOLS_DIR = path.join(ROOT, 'src', 'lib', 'prompts', 'tools');
const OUTPUT_FILE = path.join(ROOT, 'src', 'lib', 'prompts', '_system-prompt-bundle.ts');
const AGENTS_OUTPUT = path.join(ROOT, 'src', 'lib', 'prompts', '_agent-prompts-bundle.ts');
const TOOLS_OUTPUT = path.join(ROOT, 'src', 'lib', 'prompts', '_tool-descriptions-bundle.ts');

function readPromptFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((f) => f.endsWith('.md'))
    .sort() // alphabetical = numeric prefix ordering (01-, 02-, etc.)
    .map((f) => {
      const raw = fs.readFileSync(path.join(dir, f), 'utf-8');
      // Strip HTML comment frontmatter (<!-- ... -->) from the top.
      const content = raw.replace(/^<!--[\s\S]*?-->\s*/, '').trim();
      return { name: f, content };
    });
}

function buildBundle() {
  const fragments = readPromptFiles(PROMPTS_DIR);

  if (fragments.length === 0) {
    console.warn('[prompts] No .md files found in', PROMPTS_DIR);
    return;
  }

  // Concatenate all fragments with double newlines between them.
  const assembled = fragments
    .map((f) => f.content)
    .join('\n\n');

  // Generate the TS module.
  const ts = `/**
 * AUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.
 * Source: src/lib/prompts/system/*.md (sorted alphabetically).
 * Rebuild: node build/promptMarkdownUtils.mjs
 */
export const BASE_SYSTEM_PROMPT = ${JSON.stringify(assembled)};
`;

  fs.writeFileSync(OUTPUT_FILE, ts, 'utf-8');
  console.log(`[prompts] bundled ${fragments.length} files → ${path.relative(ROOT, OUTPUT_FILE)}`);
  for (const f of fragments) {
    console.log(`  ${f.name} (${f.content.length} chars)`);
  }
}

function buildAgentBundle() {
  const agentFiles = fs.existsSync(AGENTS_DIR)
    ? fs.readdirSync(AGENTS_DIR).filter((f) => f.endsWith('.md')).sort()
    : [];

  if (agentFiles.length === 0) {
    console.warn('[prompts] No agent .md files found in', AGENTS_DIR);
    return;
  }

  // Parse frontmatter + content from each agent MD file.
  const agents = [];
  for (const f of agentFiles) {
    const raw = fs.readFileSync(path.join(AGENTS_DIR, f), 'utf-8');
    // Extract frontmatter fields.
    const nameMatch = raw.match(/name:\s*"([^"]+)"/);
    const descMatch = raw.match(/description:\s*"([^"]+)"/);
    const whenMatch = raw.match(/whenToUse:\s*"([^"]+)"/);
    const allowedToolsMatch = raw.match(/allowedTools:\s*"([^"]+)"/);
    const maxStepsMatch = raw.match(/maxSteps:\s*(\d+)/);
    const thinkingBudgetMatch = raw.match(/thinkingBudget:\s*(\d+)/);
    // Strip frontmatter for the prompt content.
    const content = raw.replace(/^<!--[\s\S]*?-->\s*/, '').trim();

    agents.push({
      name: nameMatch ? nameMatch[1] : f.replace('.md', ''),
      description: descMatch ? descMatch[1] : '',
      whenToUse: whenMatch ? whenMatch[1] : '',
      systemPrompt: content,
      allowedTools: allowedToolsMatch ? allowedToolsMatch[1].split(',').map(s => s.trim()) : undefined,
      maxSteps: maxStepsMatch ? parseInt(maxStepsMatch[1]) : undefined,
      thinkingBudget: thinkingBudgetMatch ? parseInt(thinkingBudgetMatch[1]) : undefined,
    });
  }

  const ts = `/**
 * AUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.
 * Source: src/lib/prompts/agents/*.md
 * Rebuild: node build/promptMarkdownUtils.mjs
 *
 * Each agent is dynamically loaded from its .md file — adding a new .md file
 * to src/lib/prompts/agents/ automatically creates a new builtin agent.
 * No code changes needed — just rebuild.
 */
export interface BundledAgent {
  name: string;
  description: string;
  whenToUse: string;
  systemPrompt: string;
  allowedTools?: string[];
  maxSteps?: number;
  thinkingBudget?: number;
}

export const BUNDLED_AGENTS: BundledAgent[] = ${JSON.stringify(agents, null, 2)};

/** Pre-assembled agent list for the system prompt (dispatch ordering + descriptions). */
export const AGENT_LIST_MD = ${JSON.stringify(
  '# Sub-agents — dispatch for multi-step work\n' +
  'Sub-agents run one focused LLM call with a role-tuned prompt and return a report. You stay responsible for acting on findings.\n\n' +
  '**Dispatch order:**\n' +
  '1. \`general-purpose\` FIRST — analyze task, break into subtasks, produce execution plan\n' +
  '2. \`explore\` SECOND — locate files, symbols, call sites\n' +
  '3. Specialists THIRD — domain experts as needed\n' +
  '4. Act LAST — make edits yourself using the reports\n\n' +
  '**When NOT to dispatch:**\n' +
  '- You already know the answer from prior context\n' +
  '- Single targeted lookup (one read_file, one grep)\n' +
  '- User explicitly wants you to do it directly\n\n' +
  '**Available agents:**\n' +
  agents.map((a) => '- **' + a.name + '** — ' + a.whenToUse).join('\n') + '\n\n' +
  '**How to dispatch well:**\n' +
  '- Pass a self-contained \`task\` — the agent sees only that string, not prior conversation\n' +
  '- Use the report as input to your next step; if incomplete, dispatch again with sharper instructions\n' +
  '- You may dispatch multiple agents in parallel for independent subtasks'
)};
`;

  fs.writeFileSync(AGENTS_OUTPUT, ts, 'utf-8');
  console.log(`[prompts] bundled ${agents.length} agent files → ${path.relative(ROOT, AGENTS_OUTPUT)}`);
  for (const a of agents) {
    console.log(`  ${a.name}.md (${a.systemPrompt.length} chars) — ${a.description.slice(0, 50)}`);
  }
}

function buildToolBundle() {
  const toolFiles = fs.existsSync(TOOLS_DIR)
    ? fs.readdirSync(TOOLS_DIR).filter((f) => f.endsWith('.md')).sort()
    : [];

  if (toolFiles.length === 0) {
    console.warn('[prompts] No tool .md files found in', TOOLS_DIR);
    return;
  }

  const tools = [];
  for (const f of toolFiles) {
    const raw = fs.readFileSync(path.join(TOOLS_DIR, f), 'utf-8');
    const nameMatch = raw.match(/name:\s*"([^"]+)"/);
    const descMatch = raw.match(/description:\s*"([^"]+)"/);
    const catMatch = raw.match(/category:\s*"([^"]+)"/);
    const content = raw.replace(/^<!--[\s\S]*?-->\s*/, '').trim();

    tools.push({
      name: nameMatch ? nameMatch[1] : f.replace('.md', ''),
      description: descMatch ? descMatch[1] : '',
      category: catMatch ? catMatch[1] : 'Other',
      promptText: content,
    });
  }

  // Group by category for the system prompt section.
  const categories = {};
  for (const t of tools) {
    if (!categories[t.category]) categories[t.category] = [];
    categories[t.category].push(t.promptText);
  }

  const ts = `/**
 * AUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.
 * Source: src/lib/prompts/tools/*.md
 * Rebuild: node build/promptMarkdownUtils.mjs
 *
 * Each tool description is dynamically loaded from its .md file — adding a
 * new .md file to src/lib/prompts/tools/ automatically includes it in the
 * system prompt's tool list.
 */
export interface BundledTool {
  name: string;
  description: string;
  category: string;
  promptText: string;
}

export const BUNDLED_TOOLS: BundledTool[] = ${JSON.stringify(tools, null, 2)};

/** Pre-assembled tool list grouped by category, ready for the system prompt. */
export const TOOL_LIST_MD = ${JSON.stringify(
  Object.entries(categories)
    .map(([cat, lines]) => `**${cat}:**\n` + lines.join('\n'))
    .join('\n\n')
)};
`;

  fs.writeFileSync(TOOLS_OUTPUT, ts, 'utf-8');
  console.log(`[prompts] bundled ${tools.length} tool files → ${path.relative(ROOT, TOOLS_OUTPUT)}`);
  for (const t of tools) {
    console.log(`  ${t.name}.md — ${t.category} — ${t.description.slice(0, 50)}`);
  }
}

buildBundle();
buildAgentBundle();
buildToolBundle();
